document.addEventListener('DOMContentLoaded',()=>{const side=document.querySelector('.side');if(!side)return;const profile=JSON.parse(localStorage.getItem('angra-briefing')||'{"days":"3","stay":"Centro de Angra"}');const routes={2:[['Dia 1','Centro histórico + Praia do Bonfim','caminhada · pôr do sol'],['Dia 2','Ilha da Gipóia + Praia do Dentista','barco · banho de mar']],3:[['Dia 1','Centro histórico + Praia Grande','cultura · pôr do sol'],['Dia 2','Ilha da Gipóia + Ilha Cataguás','barco · praias calmas'],['Dia 3','Ilha Grande: Abraão + Lopes Mendes','trilha · praia']],4:[['Dia 1','Centro histórico + Bonfim','cultura · praia'],['Dia 2','Ilha da Gipóia + Dentista','barco · mar calmo'],['Dia 3','Ilha Grande: Abraão + Lagoa Azul','barco · snorkel'],['Dia 4','Lopes Mendes ou Pico do Papagaio','trilha · escolha do grupo']],5:[['Dia 1','Centro histórico + Praia Grande','cultura · pôr do sol'],['Dia 2','Gipóia + Cataguás','barco · praias'],['Dia 3','Abraão + Feiticeira','trilha · cachoeira'],['Dia 4','Lopes Mendes + Caxadaço','praia · trilha'],['Dia 5','Dia flexível para parceiro de barco','reserva · mar'] ]};const panel=document.createElement('div');panel.className='route-panel';panel.innerHTML='<h4>Sugestão para sua viagem</h4><p>Base: '+profile.stay+' · '+profile.days+' dias</p><div class="route-days"></div>';side.insertBefore(panel,side.querySelector('.official')||side.lastElementChild);const days=routes[profile.days]||routes[3];panel.querySelector('.route-days').innerHTML=days.map(d=>`<div><b>${d[0]}</b><strong>${d[1]}</strong><small>${d[2]}</small></div>`).join('');const s=document.createElement('style');s.textContent='.route-panel{margin-top:18px;padding-top:16px;border-top:1px solid rgba(20,43,58,.14)}.route-panel h4{margin:0;font-size:16px}.route-panel p{font-size:12px;color:#66808b;margin:5px 0 12px}.route-days{display:grid;gap:7px}.route-days div{background:#fff;border-radius:10px;padding:10px}.route-days b{display:block;color:#f26b4f;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.route-days strong{display:block;font-size:13px;margin:3px 0}.route-days small{font-size:11px;color:#66808b}';document.head.appendChild(s)});
